<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
require_once __DIR__.'/../app/layout.php';
foreach(['core_sync_v1301.php','access_control_v1300.php','module_control_v1320.php'] as $f){$p=__DIR__.'/../app/'.$f;if(is_file($p))require_once $p;}
if(!sk1320mc_allowed()){http_response_code(403);exit('Forbidden');}
$msg='';$err='';
if(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'))==='POST'){
    try{
        if(function_exists('csrf_check'))csrf_check();
        $action=(string)($_POST['action']??'');
        if($action==='feature'){
            $key=(string)($_POST['feature_key']??'');$mode=(string)($_POST['mode']??'');
            $val=$mode==='default'?null:($mode==='on');sk1320mc_set_override($key,$val);
            if(function_exists('sk1300_audit'))sk1300_audit('module_control.feature',0,$key,['mode'=>$mode]);
            $msg='Public feature visibility updated.';
        }elseif($action==='group'){
            $group=trim((string)($_POST['group']??''));$enabled=((string)($_POST['enabled']??'1'))==='1';$n=sk1320mc_apply_group($group,$enabled);
            if(function_exists('sk1300_audit'))sk1300_audit('module_control.group',0,'',['group'=>$group,'enabled'=>$enabled,'features'=>$n]);
            $msg=$n.' feature(s) updated in '.$group.'.';
        }
    }catch(Throwable $e){$err=$e->getMessage();}
}
$r=sk1320mc_snapshot();$s=$r['summary'];$csrf=function_exists('csrf_token')?csrf_token():'';
page_start('Module Visibility Manager',true);
?>
