<script>(()=>{const i=document.getElementById('mc1320Search');if(!i)return;const rows=[...document.querySelectorAll('[data-search]')],groups=[...document.querySelectorAll('details[data-group]')];i.addEventListener('input',()=>{const q=i.value.trim().toLowerCase();rows.forEach(r=>r.classList.toggle('is-hidden',q&&!String(r.dataset.search||'').includes(q)));groups.forEach(g=>{if(!q){g.style.display='';return}const visible=[...g.querySelectorAll('tbody tr')].some(r=>!r.classList.contains('is-hidden'));g.style.display=(visible||String(g.dataset.group||'').includes(q))?'':'none';if(visible)g.open=true;});});})();</script>
